package controlplane

// Registered by the shared schema entry point only after integration review.
const migrationTargetJournalSchema = `
CREATE TABLE v3_migration_target_journals(session text PRIMARY KEY REFERENCES v3_migration_sessions(id),state text NOT NULL CHECK(state IN ('armed','sealed')),request_version bigint NOT NULL,armed_version bigint NOT NULL,sealed_version bigint NOT NULL DEFAULT 0,schema_manifest text NOT NULL,baseline_rows bigint NOT NULL DEFAULT 0,baseline_digest text NOT NULL,change_count bigint NOT NULL DEFAULT 0,upper_sequence bigint NOT NULL DEFAULT 0,seal_digest text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX v3_migration_one_target_journal ON v3_migration_target_journals((true));
CREATE TABLE v3_migration_target_tables(session text NOT NULL REFERENCES v3_migration_target_journals(session),table_name text NOT NULL,primary_keys jsonb NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(session,table_name));
CREATE TABLE v3_migration_target_baselines(session text NOT NULL REFERENCES v3_migration_target_journals(session),table_name text NOT NULL,record_key jsonb NOT NULL,row_data jsonb NOT NULL,row_digest text NOT NULL,PRIMARY KEY(session,table_name,record_key));
CREATE TABLE v3_migration_target_changes(sequence bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,session text NOT NULL REFERENCES v3_migration_target_journals(session),table_name text NOT NULL,operation text NOT NULL CHECK(operation IN ('ADD','UPDATE','DELETE')),before_key jsonb NOT NULL,after_key jsonb NOT NULL,before_data jsonb NOT NULL,after_data jsonb NOT NULL,change_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX v3_migration_target_changes_session ON v3_migration_target_changes(session,sequence);
CREATE TABLE v3_migration_target_replays(session text NOT NULL REFERENCES v3_migration_target_journals(session),consumer text NOT NULL,request_version bigint NOT NULL,started_version bigint NOT NULL,finished_version bigint NOT NULL DEFAULT 0,state text NOT NULL CHECK(state IN ('baseline','changes','complete')),cursor_table text NOT NULL DEFAULT '',cursor_key text NOT NULL DEFAULT '',cursor_sequence bigint NOT NULL DEFAULT 0,rows bigint NOT NULL DEFAULT 0,digest text NOT NULL,PRIMARY KEY(session,consumer));
`
